#!/usr/bin/env python3
"""List UniFi clients matching the dotfiles principals. Never prints the API key."""
import json, ssl, sys, urllib.request, os

KEY = os.path.expanduser("~/.config/unifi/api-key")
HOST = os.environ.get("UNIFI_LOCAL_HOST", "10.0.0.1")
WANT = {"utsuho", "setsuna", "kyuusaku", "fujiwara", "mari", "shiori"}

try:
    with open(KEY) as f:
        key = f.readline().strip()
except OSError as e:
    sys.exit(f"cannot read the api key file: {e.strerror}")
if not key:
    sys.exit("api key file is empty")

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

def get(path):
    req = urllib.request.Request(f"https://{HOST}{path}")
    req.add_header("X-API-KEY", key)
    req.add_header("Accept", "application/json")
    with urllib.request.urlopen(req, context=ctx, timeout=20) as r:
        return json.load(r)

for path in ("/proxy/network/integration/v1/sites",
             "/proxy/network/api/s/default/stat/sta"):
    try:
        d = get(path)
        print(f"OK   {path}  -> {type(d).__name__}")
        if "integration" in path:
            sites = d.get("data", d if isinstance(d, list) else [])
            for s in sites:
                print("     site:", s.get("id"), s.get("name") or s.get("desc"))
        else:
            rows = d.get("data", [])
            print(f"     {len(rows)} clients total")
            for c in rows:
                names = {str(c.get(k, "")).lower() for k in ("name", "hostname", "display_name")}
                if names & WANT or any(w in n for n in names if n for w in WANT):
                    print("     MATCH %-12s ip=%-15s mac=%s wired=%s" % (
                        c.get("name") or c.get("hostname") or "?",
                        c.get("ip") or c.get("last_ip") or "-",
                        c.get("mac", "-"), not c.get("is_wireless", False)))
    except Exception as e:
        print(f"FAIL {path}: {type(e).__name__}: {e}")
PYEOF
